<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { CalendarCheck, CarFront, Users, Wallet, ArrowUpRight, CircleCheck, Plus } from 'lucide-vue-next'
import { readData, currentSession } from '../services/storage'
import { money, dateTime } from '../services/fareService'
import { useRouter } from 'vue-router'
const router=useRouter(), tick=ref(0), data=computed(()=>{tick.value;return readData()}), user=currentSession(), isAdmin=user?.role==='admin'
const stats=computed(()=>[
 {label:'Total bookings',value:data.value.bookings.length,detail:'All recorded rides',icon:CalendarCheck,tone:'blue'},
 {label:'Available drivers',value:data.value.drivers.filter(d=>d.status==='Available'&&!data.value.bookings.some(b=>['Confirmed','In Progress'].includes(b.status)&&b.driverId===d.id)).length,detail:`${data.value.drivers.length} drivers in fleet`,icon:Users,tone:'violet'},
 {label:'Available vehicles',value:data.value.vehicles.filter(v=>v.status==='Available'&&!data.value.bookings.some(b=>['Confirmed','In Progress'].includes(b.status)&&b.vehicleId===v.id)).length,detail:`${data.value.vehicles.length} vehicles registered`,icon:CarFront,tone:'green'},
 {label:'Paid revenue',value:money(data.value.payments.filter(p=>p.status==='Paid').reduce((s,p)=>s+Number(p.amount),0)),detail:'Recorded paid payments',icon:Wallet,tone:'amber'}
])
const pending=computed(()=>data.value.bookings.filter(b=>b.status==='Pending').length)
const completed=computed(()=>data.value.bookings.filter(b=>b.status==='Completed').length)
const completion=computed(()=>data.value.bookings.length?Math.round(completed.value/data.value.bookings.length*100):0)
const recent=computed(()=>[...data.value.bookings].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5))
const drivers=computed(()=>data.value.drivers)
const refresh=()=>tick.value++
onMounted(()=>window.addEventListener('taxigo:data-updated',refresh));onUnmounted(()=>window.removeEventListener('taxigo:data-updated',refresh))
</script>
<template><div class="page-heading"><div><div class="eyebrow">OVERVIEW</div><h1>Good day, {{ user?.name?.split(' ')[0] || 'there' }} <span class="wave">✦</span></h1><p>Here’s what’s happening across your taxi operations today.</p></div><button class="btn btn-primary" @click="router.push(isAdmin?'/admin/bookings':'/passenger/bookings')"><Plus :size="17"/> {{ isAdmin?'Manage bookings':'Book a ride' }}</button></div>
<div class="welcome-banner"><div class="welcome-content"><div class="welcome-tag"><span></span> TAXIGO OPERATIONS</div><h2>{{ data.bookings.length }} rides in your workspace</h2><p>{{ pending }} booking{{pending===1?'':'s'}} waiting for review. Keep your fleet moving smoothly.</p><button class="banner-link" @click="router.push(isAdmin?'/admin/bookings':'/passenger/bookings')">View bookings <ArrowRight :size="16"/></button></div><div class="welcome-art"><div class="art-circle circle-a"></div><div class="art-circle circle-b"></div><CarFront :size="104" stroke-width="1.1"/></div></div>
<div class="stats-grid"><article v-for="s in stats" :key="s.label" class="stat-card"><div class="stat-top"><span>{{s.label}}</span><span class="stat-icon" :class="s.tone"><component :is="s.icon" :size="19"/></span></div><strong class="stat-value">{{s.value}}</strong><div class="stat-foot"><span class="stat-foot-dot"></span>{{s.detail}}</div></article></div>
<div class="dashboard-grid"><section class="panel recent-panel"><div class="panel-heading"><div><h3>Recent bookings</h3><p>Latest activity from your ride queue</p></div><button class="text-button" @click="router.push(isAdmin?'/admin/bookings':'/passenger/bookings')">View all <ArrowUpRight :size="15"/></button></div><div v-if="recent.length" class="table-wrap"><table><thead><tr><th>BOOKING</th><th>ROUTE</th><th>DATE & TIME</th><th>STATUS</th><th>FARE</th></tr></thead><tbody><tr v-for="b in recent" :key="b.id"><td><strong class="booking-code">{{b.code}}</strong><small class="cell-sub">{{b.passengerName}}</small></td><td><div class="route-cell"><span>{{b.pickup}}</span><span class="route-arrow">↓</span><span>{{b.destination}}</span></div></td><td>{{dateTime(b.scheduledAt)}}</td><td><span class="status-pill" :class="b.status.toLowerCase().replaceAll(' ','-')">{{b.status}}</span></td><td><strong>{{money(b.fare)}}</strong></td></tr></tbody></table></div><div v-else class="empty-state"><CalendarCheck :size="30"/><strong>No bookings yet</strong><p>New bookings will appear here.</p></div></section>
<section class="panel fleet-panel"><div class="panel-heading"><div><h3>Fleet overview</h3><p>Driver availability</p></div><Users :size="19" class="muted-icon"/></div><div class="fleet-summary"><div><span>Fleet readiness</span><strong>{{drivers.length?Math.round(drivers.filter(d=>d.status==='Available').length/drivers.length*100):0}}%</strong></div><div class="progress-track"><div class="progress-fill" :style="{width:(drivers.length?drivers.filter(d=>d.status==='Available').length/drivers.length*100:0)+'%'}"></div></div></div><div class="fleet-list"><div v-for="d in drivers.slice(0,4)" :key="d.id" class="fleet-row"><div class="driver-avatar">{{d.name.split(' ').map(s=>s[0]).slice(0,2).join('')}}</div><div class="fleet-person"><strong>{{d.name}}</strong><small>{{d.license}}</small></div><span class="status-pill" :class="d.status.toLowerCase().replace(' ','-')">{{d.status}}</span></div></div><button class="btn btn-secondary btn-full fleet-button" @click="router.push('/admin/drivers')">Manage drivers <ArrowRight :size="16"/></button></section></div>
<div class="bottom-insight"><div class="insight-icon"><CircleCheck :size="20"/></div><div><strong>{{completion}}% completion rate</strong><p>{{completed}} of {{data.bookings.length}} recorded bookings are completed. This metric updates automatically with ride status changes.</p></div><div class="insight-progress"><span :style="{width:completion+'%'}"></span></div></div>
</template>